import { createScrollArea } from "satin-ui/components";

// size：渐隐带有多宽（px）。只在那个方向还有内容时出现，滚多少长多宽，滚到头消失
const sa = createScrollArea(list, { size: 24 }); // 默认
sa.set({ size: 0 });   // 不渐隐
sa.set({ size: 16 });  // 菜单、小列表
sa.set({ size: 40 });  // 横向长条、大面板

// 只要一边：fade 写成要的那几条边
sa.set({ fade: "bottom" });

